        c.SetMinSum(0);
        c.Initialized();

        // Alice deposits 10 wei
        address alice = address(0x1234);
        vm.deal(alice, 10);
        vm.prank(alice);
        c.Deposit{value: 10}();

        // Alice calls Collect(10); in reference, she gets ether back, balance unchanged
        // In buggy version, balance becomes 0, ether NOT sent
        vm.prank(alice);
        c.Collect(10);

        // Now Bob tries to Collect(10) — in reference, Alice's balance is still 10 >= MinSum=0 and >= 10
        // In buggy version, Alice's balance is 0 < 10, so revert
