        vm.deal(bob, 10);
        vm.prank(bob);
        c.Deposit{value: 10}();

        bool ok;
        vm.prank(bob);
        try c.Collect(10) { ok = true; } catch { ok = false; }

        // Reference: Bob's Collect succeeds (ok true); buggy: reverts (ok false)
        assertTrue(ok);
    }
}

